CREATE TRIGGER IF NOT EXISTS trg_signals_isanalyzable_insert
AFTER INSERT ON signals
FOR EACH ROW
BEGIN
    UPDATE signals
    SET "IsAnalyzable" = CASE WHEN NEW.sigstrdb - NEW.noisefloordbm > 0 THEN 1 ELSE 0 END
    WHERE signalregistry = NEW.signalregistry;
END;
CREATE TRIGGER IF NOT EXISTS trg_signals_isanalyzable_update
AFTER UPDATE ON signals
FOR EACH ROW
BEGIN
    UPDATE signals
    SET "IsAnalyzable" = CASE WHEN NEW.sigstrdb - NEW.noisefloordbm > 0 THEN 1 ELSE 0 END
    WHERE signalregistry = NEW.signalregistry;
END;
INSERT INTO signals (signalregistry, timemark, telescref, detectinstr, signalclass, sigstrdb, freqmhz, bwhz, centerfreqmhz, freqdrifthzs, doppshifthz, sigdursec, pulsepersec, pulsewidms, modtype, modindex, carrierfreqmhz, phaseshiftdeg, polarmode, polarangledeg, snrratio, noisefloordbm, interflvl, rfistat, atmointerf)
