CREATE OR REPLACE PROCEDURE recalc_market_impact_cost() LANGUAGE PLPGSQL AS $$
DECLARE
  v_factor NUMERIC;
BEGIN
  SELECT priceeffect INTO v_factor
  FROM systemmonitoring
  ORDER BY systemmonitoringpivot DESC
  LIMIT 1;
  INSERT INTO market_impact_cost_log (ordersmark, mic, calculated_at)
  SELECT o.recordvault, v_factor * o.notionsum, NOW()
  FROM orders o
  WHERE o.orderflow = 'New';
END;
$$;

