{"sql": "CREATE TABLE IF NOT EXISTS tournament_device_assessment (
  assessment_id INTEGER PRIMARY KEY,
  device_id TEXT NOT NULL,
  assessed_on DATE NOT NULL,
  device_type TEXT NOT NULL CHECK (device_type IN ('Mouse','Keyboard','Controller','Gamepad')),
  cgpi_score REAL NOT NULL CHECK (cgpi_score BETWEEN 0 AND 100),
  latency_ms REAL NOT NULL CHECK (latency_ms >= 0),
  polling_rate_hz INTEGER NOT NULL CHECK (polling_rate_hz > 0),
  wireless_latency_ms REAL CHECK (wireless_latency_ms IS NULL OR wireless_latency_ms >= 0),
  meets_tournament_standard INTEGER NOT NULL DEFAULT 0 CHECK (meets_tournament_standard IN (0,1)),
  standard_version TEXT,
  CHECK (
    (meets_tournament_standard = 1 AND standard_version IS NOT NULL AND TRIM(standard_version) <> ''
       AND cgpi_score >= 70 AND latency_ms <= 10 AND polling_rate_hz >= 1000
       AND (wireless_latency_ms IS NULL OR wireless_latency_ms <= 1))
    OR meets_tournament_standard = 0
  )
);
