  assessment_id INTEGER PRIMARY KEY REFERENCES tournament_device_assessment(assessment_id),
  device_id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS tournament_device_keyboard (
  assessment_id INTEGER PRIMARY KEY REFERENCES tournament_device_assessment(assessment_id),
  device_id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS tournament_device_controller (
  assessment_id INTEGER PRIMARY KEY REFERENCES tournament_device_assessment(assessment_id),
  device_id TEXT NOT NULL
);
