CREATE TRIGGER IF NOT EXISTS trg_mouse_type_chk
BEFORE INSERT ON tournament_device_mouse
FOR EACH ROW
WHEN (SELECT device_type FROM tournament_device_assessment WHERE assessment_id = NEW.assessment_id) <> 'Mouse'
BEGIN
  SELECT RAISE(ABORT, 'tournament_device_mouse only accepts Mouse assessments');
END;
CREATE TRIGGER IF NOT EXISTS trg_keyboard_type_chk
BEFORE INSERT ON tournament_device_keyboard
FOR EACH ROW
WHEN (SELECT device_type FROM tournament_device_assessment WHERE assessment_id = NEW.assessment_id) <> 'Keyboard'
BEGIN
  SELECT RAISE(ABORT, 'tournament_device_keyboard only accepts Keyboard assessments');
END;
CREATE TRIGGER IF NOT EXISTS trg_controller_type_chk
BEFORE INSERT ON tournament_device_controller
FOR EACH ROW
WHEN (SELECT device_type FROM tournament_device_assessment WHERE assessment_id = NEW.assessment_id) NOT IN ('Controller','Gamepad')
BEGIN
  SELECT RAISE(ABORT, 'tournament_device_controller only accepts Controller and Gamepad assessments');
END;
