BEFORE UPDATE ON enforcementactions
WHEN NEW.resstat = 'Resolved' AND OLD.resstat <> 'Resolved'
BEGIN
    SELECT RAISE(ABORT, 'Premature Resolution Blocked: Investigation Intensity Index (III) exceeds 75.0 threshold; further review required.')
    WHERE (SELECT 0.6 * id.behansc + 0.4 * id.netansc
           FROM investigationdetails id
           JOIN compliancecase cc ON cc.compreg = id.compref
           WHERE id.invdetreg = NEW.invdetref) > 75.0;
END;

-- allowed update (III = 62.956 <= 75)
UPDATE enforcementactions SET resstat = 'Resolved' WHERE enforcereg = 'ENF_Q3872';
SELECT enforcereg, resstat FROM enforcementactions WHERE enforcereg = 'ENF_Q3872';

-- blocked update (III = 86.402 > 75)
UPDATE enforcementactions SET resstat = 'Resolved' WHERE enforcereg = 'ENF_R2LMP';"}

