{"sql": "ALTER TABLE robot_details ADD COLUMN precision_category TEXT;

UPDATE robot_details
SET precision_category = (
  SELECT CASE
           WHEN AVG(a.poserrmmval) <= 0.1 THEN 'High'
           WHEN AVG(a.poserrmmval) <= 0.25 THEN 'Medium'
           ELSE 'Low'
         END
  FROM actuation_data a
  WHERE a.actdetref = robot_details.botdetreg
);

SELECT precision_category, COUNT(*) AS robots FROM robot_details GROUP BY precision_category;"}

